rep("  // puntos de hoy y misiones\n","  const PA=mpS().pausa; if (PA&&k<=PA.b) h+=`<div class=\"banner\" style=\"margin-top:10px;border-color:#4da3ff\"><span class=\"ic\" style=\"color:#4da3ff\">${I('heart',18)}</span><div class=\"grow xs\">${tx(`Racha en pausa hasta el ${new Date(mpK(PA.b)).toLocaleDateString(LOC(),{day:'numeric',month:'long'})}: los días sin cumplir no la rompen. Cuídate.`,`Streak paused until ${new Date(mpK(PA.b)).toLocaleDateString(LOC(),{day:'numeric',month:'long'})}: missed days will not break it. Take care.`,{pt:`Sequência pausada até ${new Date(mpK(PA.b)).toLocaleDateString(LOC(),{day:'numeric',month:'long'})}: os dias sem cumprir não a quebram. Cuide-se.`})} <button class=\"link sm\" data-a=\"mpPausaFin\">${tx('Reanudar','Resume',{pt:'Retomar'})}</button></div></div>`;\n  // puntos de hoy y misiones\n")
